using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
public partial class MigrationScene {
 sealed class FriendlyAvatar{public Infected Mover;public Label3D Label;public Node3D Tool;public string ToolMode="";}
 readonly Dictionary<string,FriendlyAvatar> communityAvatars=new();int communitySeed=int.MinValue;bool communityFixture;double communityShotFx;
 ExpeditionCommunity Community=>game.World.Changes.Community;
 string CommunityOwner=>CoopHost&&coopActor>0&&coopActors.TryGetValue(coopActor,out var actor)?actor.Identity:coopIdentity??"local";
 (ExpeditionGame Game,CharacterBody3D Body)? CommunityLeader(string owner){if(string.IsNullOrEmpty(owner))return null;if(!CoopActive)return owner==CommunityOwner?(game,player):null;if(CoopHost){if(owner==coopIdentity)return(coopHostGame,GetNode<CharacterBody3D>("Survivor"));var actor=coopActors.Values.FirstOrDefault(a=>a.Identity==owner);if(actor!=null)return(actor.Game,actor.Body);}return null;}
 Vector3 NpcPoint(CampSurvivor n)=>new((float)n.X,(float)n.Y,(float)n.Z);
 IEnumerable<string> RescueGuardIds(CampSurvivor n)=>Enumerable.Range(0,2+n.Encounter).Select(i=>$"rescue/{game.Save.Seed}/{n.Encounter}/guard/{i}");
 Vector3 RescuePoint(CampSurvivor n){double z=new double[]{-240,-560,-1080}[n.Encounter];return Ground(game.World.RouteX(z)+(n.Encounter==1?-14:14),z);}
 void SpawnCommunity(){Community.Seed(game.World);if(communitySeed!=game.Save.Seed){foreach(var a in communityAvatars.Values)a.Mover.Body.QueueFree();communityAvatars.Clear();communitySeed=game.Save.Seed;}if((testing||coopCheckRole!=null)&&!communityFixture)return;if(dungeon!=null)return;
  foreach(var n in Community.Survivors){if(n.State=="dead"){if(communityAvatars.Remove(n.Id,out var lost))lost.Mover.Body.QueueFree();continue;}var position=NpcPoint(n);bool near=CoopHost?NearActiveSurface(position,180):Distance(position,player.Position)<180;
   if(!near){if(communityAvatars.Remove(n.Id,out var old))old.Mover.Body.QueueFree();continue;}if(!communityAvatars.ContainsKey(n.Id)){if(n.State=="trapped"&&!OutdoorFree(n.X,n.Z)){for(int i=1;i<8;i++)if(OutdoorFree(n.X+i*1.3,n.Z)){n.X+=i*1.3;n.Y=game.World.Height(n.X,n.Z);break;}}BuildFriendly(n);}
   if(n.State!="trapped"){foreach(var site in props.Where(p=>p.Kind==17&&p.Id==n.Id+"/shelter"))foreach(var label in site.Node.GetChildren().OfType<Label3D>())if(label.Text.Contains("HELP!"))label.Text="RESCUE SITE / CLEARED";continue;}string siteId=n.Id+"/shelter";if(uniqueObjects.Add(siteId)){var site=new Node3D{Position=RescuePoint(n)};worldRoot.AddChild(site);if(n.Encounter==0)DressAbandonedStop(site,0);else{for(int i=0;i<3;i++)Bevel(site,new(-2+i*1.4f,.3f,-2),new(.8f,.6f,.7f),Wood);Box(site,new(2,1.2f,0),new(.2f,2.4f,4),Wood,true);}site.AddChild(new Label3D{Text="SURVIVOR / HELP!",Position=new(0,3.3f,0),FontSize=30,PixelSize=.008f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,Modulate=new(.38f,.80f,.74f)});props.Add(new(){Id=siteId,Kind=17,Node=site,Position=site.Position});}
   if(CoopClient)continue;int guardIndex=0;foreach(string id in RescueGuardIds(n)){if(game.Skills.Defeated.Contains(id)||infected.Any(e=>e.Id==id)){guardIndex++;continue;}for(int attempt=0;attempt<20;attempt++){float angle=guardIndex*2.1f+attempt*.47f;var p=RescuePoint(n)+new Vector3(Mathf.Sin(angle)*(8+attempt%4*2),0,Mathf.Cos(angle)*(8+attempt%4*2));if(attempt>=16)p=Ground(game.World.RouteX(RescuePoint(n).Z+guardIndex*3+attempt),RescuePoint(n).Z+guardIndex*3+attempt);if(!OutdoorFree(p.X,p.Z))continue;AddEnemy(id,p.X,p.Z,Math.Min(3,1+n.Encounter));if(infected.Any(e=>e.Id==id))break;}guardIndex++;}
  }
 }
 void BuildFriendly(CampSurvivor n){var body=new CharacterBody3D{Name="FriendlySurvivor",Position=NpcPoint(n),Rotation=new(0,(float)n.Yaw,0),FloorSnapLength=.5f,CollisionLayer=2,CollisionMask=1};body.AddChild(new CollisionShape3D{Position=new(0,.88f,0),Shape=new CapsuleShape3D{Radius=.3f,Height=1.75f}});var visual=new Node3D();body.AddChild(visual);HumanCharacter(visual,1,0,true);var torso=visual.GetNode<Node3D>("Torso");Bevel(torso,new(.12f,.35f,-.14f),new(.10f,.08f,.025f),n.Encounter==0?new Color(.55f,.25f,.17f):n.Encounter==1?new Color(.25f,.42f,.55f):new Color(.58f,.49f,.22f));var label=new Label3D{Position=new(0,2.1f,0),FontSize=25,PixelSize=.006f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,Modulate=new(.39f,.85f,.79f)};body.AddChild(label);AddChild(body);communityAvatars[n.Id]=new(){Mover=new Infected{Id="friendly/"+n.Id,Body=body,Visual=visual,Home=body.Position},Label=label};}
 CampSurvivor NearCommunity(float reach=3.5f)=>dungeon!=null?null:Community.Survivors.Where(n=>n.State!="dead"&&communityAvatars.ContainsKey(n.Id)&&Distance(NpcPoint(n),player.Position)<reach).OrderBy(n=>Distance(NpcPoint(n),player.Position)).FirstOrDefault();
 void DrawCommunity(double dt){if((testing||coopCheckRole!=null)&&!communityFixture)return;SpawnCommunity();foreach(var n in Community.Survivors){if(!communityAvatars.TryGetValue(n.Id,out var a))continue;UpdateFriendlyTool(n,a);var e=a.Mover;foreach(var shape in e.Body.GetChildren().OfType<CollisionShape3D>())if(shape.Disabled!=(dungeon!=null))shape.SetDeferred(CollisionShape3D.PropertyName.Disabled,dungeon!=null);e.Body.Visible=dungeon==null&&Distance(player.Position,NpcPoint(n))<160;if(CoopClient){e.Body.Position=e.Body.Position.Lerp(NpcPoint(n),Math.Min(1,(float)dt*12));e.Body.Rotation=new(0,(float)n.Yaw,0);}a.Label.Text=n.Name+" / "+(n.Downed?$"FIRST AID / {Math.Ceiling(Math.Max(0,ExpeditionCommunity.RescueWindow-n.DownTime)):0}s LEFT":n.State=="trapped"?"NEEDS RESCUE":n.State=="rescued"?"ESCORT TO YOUR CAMP":n.Pose=="fireside"?"AT THE FIRE":n.GriefRemaining>0?"MOURNING "+n.GrievingFor:!string.IsNullOrEmpty(n.Owner)?"COMPANION":n.Job.ToUpperInvariant())+$"\nHP {n.Health:0} / MORALE {n.Morale:0}";
   e.Visual.Position=n.Downed?new(0,.2f,0):Vector3.Zero;e.Visual.Rotation=n.Downed?new(Mathf.Pi/2,0,0):Vector3.Zero;if(!n.Downed){PoseFigure(e.Visual,(float)(game.Clock*5+n.Encounter),n.Pose=="walk"?1:0,false);if(n.Pose=="shoot")foreach(string side in new[]{"Left","Right"})e.Visual.GetNode<Node3D>(side+"Arm").RotationDegrees=new(-80,0,side=="Left"?10:-10);if(n.Pose=="supplies")foreach(string side in new[]{"Left","Right"})e.Visual.GetNode<Node3D>(side+"Arm").RotationDegrees=new(-55,0,0);if(n.GriefRemaining>0&&n.Pose=="idle")e.Visual.GetNode<Node3D>("Torso").RotationDegrees=new(9,0,0);if(n.Pose=="fireside"){foreach(string side in new[]{"Left","Right"})e.Visual.GetNode<Node3D>(side+"Arm").RotationDegrees=new(-18,0,side=="Left"?8:-8);e.Visual.GetNode<Node3D>("Torso").RotationDegrees=new(4,0,0);}if(n.Pose=="wood")e.Visual.GetNode<Node3D>("RightArm").RotationDegrees=new(-65+Mathf.Sin((float)game.Clock*3)*35,0,-15);}
  }
 }
}
